const AUTH_URL = import.meta.env.VITE_AUTH_URL || 'https://mantek-auth.vercel.app';

const mapAuthRoleToErp = (authRole) => {
  const map = {
    ADMIN:'supervisor', SUPERVISOR:'supervisor', MECANICO:'mecanico',
    OPERADOR:'operador', INVITADO:'operador', GERENTE:'operaciones',
    JEFE_OPERACIONES:'operaciones', SUP_OPERACIONES:'operaciones',
  };
  return map[authRole] || 'operador';
};

const buildErpPerms = (authPerms) => {
  if(!authPerms) return {};
  const keyMap = {
    workorders:'workorders', checklist:'checklist', requests:'requests',
    plans:'plans', equipment:'equipment', indicadores:'indicadores',
    reports:'reports', repuestos:'repuestos', vessels:'vessels',
    users:'users', config:'config_reportes', dashboard:'dashboard',
  };
  const result = {};
  Object.entries(authPerms).forEach(([k,v]) => { result[keyMap[k]||k] = v; });
  return result;
};
