/*
 * ── CONFIGURACIÓN EMAILJS SGN ──────────────────────────────
 * 1. Ve a https://emailjs.com → Login
 * 2. Email Services → tu servicio → copia SERVICE_ID → EJS_SERVICE
 * 3. Account → API Keys → copia Public Key → EJS_KEY
 *
 * Crea 3 plantillas y copia sus template_id:
 *
 * TPL 1 (EJS_TPL_ASIGNADO) — Asunto: [SGN] Hallazgo asignado {{numero_hallazgo}}
 *   Variables: to_email, to_name, numero_hallazgo, fuente, lugar,
 *              fecha, descripcion, originador, url_app
 *
 * TPL 2 (EJS_TPL_RESPONDIDO) — Asunto: [SGN] Respuesta recibida {{numero_hallazgo}}
 *   Variables: to_email, numero_hallazgo, responsable,
 *              fecha_respuesta, url_app
 *
 * TPL 3 (EJS_TPL_RECORDATORIO) — Asunto: [SGN] ⚠️ Hallazgo pendiente {{numero_hallazgo}}
 *   Variables: to_email, to_name, numero_hallazgo, dias_vencidos, url_app
 * ──────────────────────────────────────────────────────────
 */
const EJS_SERVICE          = import.meta.env.VITE_EJS_SERVICE  || "";
const EJS_KEY              = import.meta.env.VITE_EJS_KEY      || "";
const EJS_TPL_ASIGNADO     = import.meta.env.VITE_EJS_TPL_RESPONSABLE  || "";
const EJS_TPL_RESPONDIDO   = import.meta.env.VITE_EJS_TPL_AUDITOR      || "";
const EJS_TPL_RECORDATORIO = import.meta.env.VITE_EJS_TPL_RESPONSABLE  || "";
const APP_URL = "https://erp-navimag-pefgrnqe0-silva1655-boops-projects.vercel.app";

const ejsSend=async(tpl,params)=>{
  if(!EJS_SERVICE||!EJS_KEY||!tpl) return false;
  try{await emailjs.send(EJS_SERVICE,tpl,params,EJS_KEY);return true;}
  catch(e){console.warn("EmailJS:",e);return false;}
};
const notifAsignado=(h)=>ejsSend(EJS_TPL_ASIGNADO,{
  to_email:h.responsableEmail,to_name:h.responsableNombre,
  numero_hallazgo:h.numero||"—",fuente:h.fuente||"—",
  lugar:h.lugar||h.nave||"—",fecha:h.fecha||"—",
  descripcion:(h.descripcionIncumplimiento||h.descripcion||"—").slice(0,300),
  originador:h.createdBy||"—",url_app:APP_URL,
});
const notifRespondido=(h,emailAuditor)=>ejsSend(EJS_TPL_RESPONDIDO,{
  to_email:emailAuditor,numero_hallazgo:h.numero||"—",
  responsable:h.responsableNombre||"—",
  fecha_respuesta:new Date().toLocaleDateString("es-CL"),url_app:APP_URL,
});
const notifRecordatorio=(h,diasVencidos)=>ejsSend(EJS_TPL_RECORDATORIO,{
  to_email:h.responsableEmail,to_name:h.responsableNombre,
  numero_hallazgo:h.numero||"—",dias_vencidos:diasVencidos,url_app:APP_URL,
});

