function makeSaveData(coll){
  return async function saveData(key, arr) {
    try {
      const payload = JSON.stringify({data:arr});
      const sizeKB = Math.round(payload.length / 1024);
      if(sizeKB > 900){
        console.warn(`⚠️ saveData "${key}": ${sizeKB}KB — cerca del límite`);
      }
      if(sizeKB > 1000){
        console.error(`🚨 saveData "${key}": ${sizeKB}KB supera límite`);
        alert(`Error: datos de "${key}" superan límite (${sizeKB}KB).`);
        return;
      }
      await setDoc(doc(db,coll,key),{data:arr});
    } catch(e) { console.error("Save:",e); }
  };
}
function makeAppendToArray(coll){
  return async function appendToArray(key, newItem) {
    try {
      const ref = doc(db, coll, key);
      await runTransaction(db, async (tx) => {
        const snap = await tx.get(ref);
        const current = snap.exists() ? snap.data().data : [];
        if (current.find(i => i.id === newItem.id)) return;
        tx.set(ref, { data: [...current, newItem] });
      });
    } catch(e) { console.error("appendToArray:", e); }
  };
}
function makeUpdateInArray(coll){
  return async function updateInArray(key, updatedItem) {
    try {
      const ref = doc(db, coll, key);
      await runTransaction(db, async (tx) => {
        const snap = await tx.get(ref);
        const current = snap.exists() ? snap.data().data : [];
        tx.set(ref, { data: current.map(i => i.id === updatedItem.id ? updatedItem : i) });
      });
    } catch(e) { console.error("updateInArray:", e); }
  };
}
