async function recordLogin(coll, user) {
  try {
    const ref = doc(db, coll, "loginHistory");
    await runTransaction(db, async (tx) => {
      const snap = await tx.get(ref);
      const current = snap.exists() ? snap.data().data : [];
      tx.set(ref, {
        data: [...current, {
          id: uid(),
          userId:   user.id,
          userName: user.name,
          avatar:   user.avatar,
          role:     user.role,
          loginAt:  new Date().toISOString(),
          date:     new Date().toISOString().slice(0,10),
          month:    new Date().toISOString().slice(0,7),
          week:     getWeekKey(new Date()),
        }]
      });
    });
  } catch(e) { console.error("recordLogin:", e); }
}

function getWeekKey(date) {
  const d = new Date(date);
  d.setHours(0,0,0,0);
  d.setDate(d.getDate() - d.getDay() + 1); // Monday
  return d.toISOString().slice(0,10);
}

// Número de semana ISO-8601 (1-53), usado por Faena/Disponibilidad y Utilización.
function getISOWeek(date){
  const d=new Date(Date.UTC(date.getFullYear(),date.getMonth(),date.getDate()));
  const dayNum=(d.getUTCDay()+6)%7; // lunes=0 ... domingo=6
  d.setUTCDate(d.getUTCDate()-dayNum+3); // jueves de esa semana
  const firstThursday=new Date(Date.UTC(d.getUTCFullYear(),0,4));
  const firstDayNum=(firstThursday.getUTCDay()+6)%7;
  firstThursday.setUTCDate(firstThursday.getUTCDate()-firstDayNum+3);
  return 1+Math.round((d-firstThursday)/(7*24*3600*1000));
}

// Campos derivados de una Faena. indisponibilidadHH es la suma de
// horasReparacion de las Detenciones asociadas (bloque 3 la recalcula en el
// cliente al guardar/editar/borrar una Detención).
//
// Fórmulas validadas contra el Excel real (Registro_Detenciones_Tractos.xlsx,
// hoja Faena) leyendo las fórmulas de celda reales de columnas F/H/L/M/N/O/P/T
// (no solo el texto del spec) sobre las 180 filas históricas: coinciden
// exactamente salvo 6 filas donde el propio Excel arrastró mal una referencia
// relativa en su columna L (bug pre-existente del archivo original).
// "horasOperacion" NO son horas de calendario: son horas-tracto entregadas
// (tractosOp × horasOperacionBruta). Así "utilizacionEsperada" (target ×
// horasOperacionBruta) y "horasOperacion" quedan en la misma unidad que
// indisponibilidadHH (suma de horas de reparación, potencialmente de varios
// tractos distintos), que es lo que hace comparables sus ratios.
function calcularFaenaDerivados({buque,terminal,inicioOp,terminoOp,tractosOp,tractosUtilizados,capacidadOperadores},targets,indisponibilidadHH=0){
  const targetRow=(targets||[]).find(t=>t.buque===buque&&t.terminal===terminal);
  if(!targetRow||!inicioOp||!terminoOp) return null;
  const target=targetRow.target;
  const ini=new Date(inicioOp), fin=new Date(terminoOp);
  if(isNaN(ini.getTime())||isNaN(fin.getTime())||fin<=ini) return null;
  const tOp=parseFloat(tractosOp)||0;
  const horasOperacionBruta=(fin-ini)/3600000;
  const utilizacionEsperada=target*horasOperacionBruta;
  const horasOperacion=tOp*horasOperacionBruta;
  const horasDescontables=Math.max(0,(target-(parseFloat(capacidadOperadores)||0))*horasOperacionBruta);
  const disponibilidadTecnica=utilizacionEsperada>0?Math.max(0,Math.min(1,(horasOperacion-indisponibilidadHH)/utilizacionEsperada)):0;
  const cumplimiento=target>0?Math.min(1,tOp/target):0;
  const utilizacion=horasOperacion>0?Math.max(0,Math.min(1,(horasOperacion-indisponibilidadHH-horasDescontables)/horasOperacion)):0;
  return{
    target,horasOperacionBruta,horasDescontables,horasOperacion,utilizacionEsperada,
    indisponibilidadHH,disponibilidadTecnica,cumplimiento,utilizacion,
    semana:getISOWeek(fin),mes:fin.getMonth()+1,anio:fin.getFullYear(),
  };
}

async function initIfEmpty(coll, key, seed) {
try { const s=await getDoc(doc(db,coll,key)); if(!s.exists()) await setDoc(doc(db,coll,key),{data:seed}); } catch(e) { console.error("Init:",e); }
}
async function mergeUsers(coll, seed) {
try {
const s=await getDoc(doc(db,coll,"users"));
if(!s.exists()){
  await setDoc(doc(db,coll,"users"),{data:seed});
} else {
  const existing=s.data().data||[];
  // IDs de seeds que fueron eliminados explícitamente (marcados con deleted:true por deleteUser)
  const deletedIds=new Set(existing.filter(u=>u.deleted===true).map(u=>u.id));
  // Solo agregar seeds que no existen Y no fueron eliminados antes
  const missing=seed.filter(su=>
    !existing.find(eu=>eu.id===su.id) && !deletedIds.has(su.id)
  );
  // Propagar cambios de rol del seed a usuarios existentes (migración operaciones→jefe_maquinas)
  const conRolActualizado=existing.map(eu=>{
    const seedUser=seed.find(su=>su.id===eu.id);
    if(seedUser&&seedUser.role!==eu.role&&!eu.deleted){
      console.log(`🔄 Rol actualizado: ${eu.name} ${eu.role}→${seedUser.role}`);
      return{...eu,role:seedUser.role};
    }
    return eu;
  });
  const hayRolActualizado=conRolActualizado.some((eu,i)=>eu.role!==existing[i].role);
  if(missing.length>0||hayRolActualizado){
    await setDoc(doc(db,coll,"users"),{data:[...conRolActualizado,...missing]});
  }
}
}catch(e){console.error("MergeUsers:",e);}
}
async function mergeTemplates(coll, seed) {
try {
const s=await getDoc(doc(db,coll,"taskTemplates"));
if(!s.exists()){await setDoc(doc(db,coll,"taskTemplates"),{data:seed});return;}
const existing=s.data().data||[];
const missing=seed.filter(st=>!existing.find(et=>et.id===st.id));
if(missing.length>0)await setDoc(doc(db,coll,"taskTemplates"),{data:[...existing,...missing]});
}catch(e){console.error("MergeTemplates:",e);}
}

// ─── UTILS ───────────────────────────────────────────────────────────────────
// Fechas "solo día" (YYYY-MM-DD, sin hora — scheduledDate, nextDueDate, etc.)
// el motor de JS las parsea como medianoche UTC. En cualquier timezone
// detrás de UTC (todo Chile) eso se muestra UN DÍA ANTES al formatear en
// hora local — ej: "2026-07-30" se veía "29-07-2026". Si viene solo la
// fecha (sin hora), se arma en hora LOCAL agregando "T00:00:00" antes de
// parsear, para que no se corra. Los timestamps completos (con hora) no se
// tocan — ahí sí corresponde mostrar en hora local, es un instante real.
const fmt   = d => {
  if(!d) return "—";
  const soloFecha=/^\d{4}-\d{2}-\d{2}$/.test(String(d));
  return new Date(soloFecha?d+"T00:00:00":d).toLocaleDateString("es-CL",{day:"2-digit",month:"2-digit",year:"numeric"});
};
const fmtDT = d => d ? new Date(d).toLocaleString("es-CL",{day:"2-digit",month:"2-digit",year:"numeric",hour:"2-digit",minute:"2-digit"}) : "—";
const uid = () => Math.random().toString(36).slice(2,10);
// Persistencia simple de filtros en localStorage (así sobreviven a navegar a
// otra pestaña y volver, o a recargar la página) — cada módulo la usa con su
// propio prefijo de key para no pisarse entre sí.
const leerLSJson=(key,fallback)=>{try{const raw=localStorage.getItem(key);return raw!=null?JSON.parse(raw):fallback;}catch{return fallback;}};
const guardarLSJson=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));}catch{}};
const addLog=(logs,action,userName,detail="")=>[
  ...(logs||[]),
  {ts:new Date().toISOString(),action,user:userName,detail}
];
const nextOTCode = wos => {
  const year=new Date().getFullYear();
  const existing=wos
    .map(w=>w.code)
    .filter(c=>c&&c.startsWith(`OT-${year}-`))
    .map(c=>parseInt(c.split("-")[2])||0);
  const max=existing.length>0?Math.max(...existing):0;
  return `OT-${year}-${String(max+1).padStart(3,"0")}`;
};
// OT generada desde un plan Marítimo: OT-{códigoPlan}-001, 002... (correlativo
// único POR plan). Solo los planes Marítimo tienen `code` — para planes de
// Taller (sin code) el llamador debe usar nextOTCode como antes.
const nextPlanOTCode=(planCode,allWOs)=>{
  const existing=allWOs
    .filter(w=>w.code&&w.code.startsWith(`OT-${planCode}-`))
    .map(w=>parseInt(w.code.split("-").pop())||0);
  const max=existing.length>0?Math.max(...existing):0;
  return `OT-${planCode}-${String(max+1).padStart(3,"0")}`;
};
const CRIT_LABEL = { A:"Crítico", B:"Importante", C:"Rutinario", alto:"Alto", medio:"Medio", bajo:"Bajo" };

const calcScoreCriticidad=(factores)=>{
  const{factorConsecuencia:C=3,factorLeadTime:LT=3,factorAlternativas:A=3,factorDetectabilidad:D=3,factorDowntime:I=3}=factores;
  const score=20*(0.35*C+0.25*LT+0.15*A+0.15*D+0.10*I);
  const clase=score>=75?"A":score>=55?"B":"C";
  return{score:Math.round(score),clase};
};

const nextREPCode=repuestos=>{
  const existing=(repuestos||[]).map(r=>r.codigo).filter(c=>c&&c.startsWith("REP-")).map(c=>parseInt(c.split("-")[1])||0);
  const max=existing.length>0?Math.max(...existing):0;
  return`REP-${String(max+1).padStart(4,"0")}`;
};

// ─── CSV EXPORT UTILITY ──────────────────────────────────────────────────────
function downloadCSV(filename, rows) {
if (!rows || rows.length === 0) return;
const headers = Object.keys(rows[0]);
const escape = v => {
const s = String(v == null ? "" : v);
if (s.includes(",") || s.includes('"') || s.includes("\n")) return `"${s.replace(/"/g, '""')}"`;
return s;
};
const lines = [headers.map(escape).join(","), ...rows.map(r => headers.map(h => escape(r[h])).join(","))];
const blob = new Blob([lines.join("\n")], { type: "text/csv;charset=utf-8;" });
const url = URL.createObjectURL(blob);
const a = document.createElement("a");
a.href = url; a.download = filename; a.click();
URL.revokeObjectURL(url);
}

