const OT_TYPES={
  preventiva:               {label:"Preventiva",             cls:"text-blue-700   bg-blue-50   border-blue-200"  },
  correctiva_planificada:   {label:"Correctiva Planificada", cls:"text-amber-700  bg-amber-50  border-amber-200" },
  correctiva_no_programada: {label:"Correctiva No Prog.",    cls:"text-orange-700 bg-orange-50 border-orange-200"},
  emergencia:               {label:"Emergencia",             cls:"text-red-700    bg-red-50    border-red-200"   },
  apoyo_operacional:        {label:"Apoyo Operacional",      cls:"text-purple-700 bg-purple-50 border-purple-200"},
};
// Backward-compat: OT viejas tienen type:"preventivo"/"correctivo" sin "a" final
const resolveOTType=w=>{
  if(OT_TYPES[w.type]) return w.type;
  if(w.type==="preventivo") return "preventiva";
  if(w.type==="correctivo") return "correctiva_no_programada";
  return null;
};

// Tipos que se consideran "falla/correctivo" para MTBF/MTTR
const esCorrectivo=w=>{
  // OTs de plan preventivo nunca afectan MTBF/MTTR, aunque su tipo sea correctivo
  if(w.source==="plan"||w.source==="planAssignment"||w.planId||w.assignmentId) return false;
  const t=resolveOTType(w)||w.type||"";
  return["correctiva_no_programada","correctiva_planificada","correctivo","emergencia"].includes(t);
};

