    ...requests.filter(r=>r.status==="ops_pendiente").slice(0,2).map(r=>({icon:Bell,color:"text-blue-500",bg:"bg-blue-50",title:"Nueva solicitud de trabajo",sub:r.title,time:r.requestedAt})),
