// ─── ERROR BOUNDARY ──────────────────────────────────────────────────────────
class ErrorBoundary extends Component {
  constructor(props){super(props);this.state={hasError:false,error:null};}
  static getDerivedStateFromError(error){return{hasError:true,error};}
  componentDidCatch(error,info){console.error("ERP Error:",error,info);}
  render(){
    if(this.state.hasError){
      return(
        <div className="flex-1 flex items-center justify-center p-8">
          <div className="bg-white border border-red-200 rounded-2xl shadow-xl p-8 max-w-md w-full text-center">
            <div className="w-12 h-12 bg-red-50 rounded-full flex items-center justify-center mx-auto mb-4 text-red-500 text-2xl font-bold">!</div>
            <h2 className="text-gray-900 font-bold text-lg mb-2">Error al cargar la sección</h2>
            <p className="text-gray-500 text-sm mb-5">{this.state.error?.message||"Ha ocurrido un error inesperado. Intenta recargar."}</p>
            <button onClick={()=>this.setState({hasError:false,error:null})} className="text-white font-semibold px-6 py-2 rounded-lg text-sm hover:opacity-90 transition" style={{background:"#0055A4"}}>Reintentar</button>
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}

