const [sortOrder,setSortOrder]=useState("atraso");
const [rejectTarget,setRejectTarget]=useState(null);
const [rejectReason,setRejectReason]=useState("");
const [rep,setRep]=useState({actualHours:"",observations:"",status:"completada",horometro:"",parts:"",plannedDate:"",plannedReason:"",photos:[],fechaInicio:new Date().toISOString().slice(0,10),horaInicio:new Date().toTimeString().slice(0,5),fechaTermino:"",horaTermino:"",fotoFalla:[],fotoResultado:[]});
const repPhotoRef=useRef(null);
  const [showSig,setShowSig]=useState(false);
const [showNewOT,setShowNewOT]=useState(false);
const [showPasoAPaso,setShowPasoAPaso]=useState(false);
const [pasoActual,setPasoActual]=useState("");
const [expandedBL,setExpandedBL]=useState(()=>new Set(Object.keys(BACKLOG_URGENCIA)));
const [selBLIds,setSelBLIds]=useState(()=>new Set());
const EMPTY_NEW_OT={equipId:"",sistema:"",sintoma:"",priority:"media",assignedTo:"",horometro:"",observations:"",type:"correctiva_no_programada",urgenciaBacklog:"programable",materialesPlanificados:[]};
const [newOTForm,setNewOTForm]=useState(EMPTY_NEW_OT);
const taxonomiaObj=useMemo(()=>getTaxonomiaComoObjeto(data.taxonomiaRepuestos||[]),[data.taxonomiaRepuestos]);

  const confirmRejectOT=()=>{
    if(!rejectReason.trim()){alert("Debes ingresar el motivo del rechazo");return;}
    updWO(rejectTarget.id,{status:"cancelada",observations:`Rechazada por ${user.name}: ${rejectReason.trim()}`},`Rechazada — ${rejectReason.trim()}`);
    setRejectTarget(null);
    setRejectReason("");
  };

  const saveNewOT=()=>{
    if(!newOTForm.equipId){alert("Selecciona el equipo");return;}
    if(!newOTForm.sintoma.trim()){alert("Describe el síntoma");return;}
    const eq=equip.find(e=>e.id===newOTForm.equipId);
    const code=nextOTCode(wos);
    const title=`${newOTForm.sistema?newOTForm.sistema+" — ":""}${newOTForm.sintoma.trim()}`;
    const newOT={
      id:uid(),
      code,
      type:newOTForm.type||"correctiva_no_programada",
      log:[{ts:new Date().toISOString(),action:"creada",user:user.name,detail:`OT manual — ${newOTForm.type?OT_TYPES[newOTForm.type]?.label||newOTForm.type:"Correctiva No Prog."}`}],
      equipId:newOTForm.equipId,
      planId:null,
      title,
      priority:newOTForm.priority||"media",
      status:newOTForm.assignedTo?"asignada":"pendiente",
      assignedTo:newOTForm.assignedTo||"",
      assignedToName:(()=>{
        if(!newOTForm.assignedTo) return "";
        const u=(users||[]).find(u=>u.id===newOTForm.assignedTo);
        return u?.name||newOTForm.assignedTo||"";
      })(),
      createdAt:new Date().toISOString(),
      scheduledDate:new Date().toISOString().slice(0,10),
      estimatedHours:0,
      actualHours:null,
      description:newOTForm.observations.trim()||title,
      observations:newOTForm.observations.trim(),
      parts:[],
      source:"manual",
      urgenciaBacklog:newOTForm.urgenciaBacklog||"programable",
      horometroInicio:newOTForm.horometro?parseFloat(newOTForm.horometro):(eq?.hours||0),
      materialesPlanificados:(newOTForm.materialesPlanificados||[]).filter(m=>m.codigo||m.descripcion).map(({_sistemaSel,_subsistemaSel,_itemSel,_modoIngreso,...resto})=>resto),
    };
    const updated=[...wos,newOT];
    setData(d=>({...d,wos:updated}));
    saveData("workOrders",updated);
    setShowNewOT(false);
    setNewOTForm(EMPTY_NEW_OT);
  };

// ── Wizard "Reportar Trabajo" (5 pasos) ──
