    if(wizardOT.reqId){
      const linkedReq=requests.find(r=>r.id===wizardOT.reqId);
      const updR=requests.map(r=>r.id===wizardOT.reqId?{...r,status:"completada"}:r);
      setData(d=>({...d,requests:updR}));
      if(linkedReq) await saveRequestIndividual(linkedReq,{status:"completada"},activeCOLL);
    }
    // ── Horómetro de cierre: valor ingresado por técnico tiene prioridad ─────
    const closingH=wz.horometroCierre
      ?parseFloat(wz.horometroCierre)
      :(equip.find(e=>e.id===wizardOT.equipId)?.hours||0);
    // closingDate/closingISO ya se calcularon arriba (fecha real de intervención)

