// ─── MARITIME PLAN UTILITIES ─────────────────────────────────────────────────
const nextPlanTemplateCode=(planTemplates)=>{
  const nums=(planTemplates||[]).map(t=>{const m=(t.code||"").match(/^PMT-(\d+)$/);return m?parseInt(m[1]):0;});
  const next=(nums.length>0?Math.max(...nums):0)+1;
  return `PMT-${String(next).padStart(4,"0")}`;
};
const nextAssignmentCode=(planAssignments,eqmCode,pmtCode)=>{
  const prefix=`PMA-${eqmCode}-${pmtCode}-`;
  const existing=(planAssignments||[]).filter(a=>(a.code||"").startsWith(prefix));
  const nums=existing.map(a=>parseInt((a.code||"").slice(prefix.length))||0);
  const next=(nums.length>0?Math.max(...nums):0)+1;
  return `${prefix}${String(next).padStart(2,"0")}`;
};
const getAssignmentStatus=(assignment,template,equipment,wos)=>{
  if(!assignment?.activo) return "inactivo";
  const openOT=(wos||[]).find(w=>w.assignmentId===assignment.id&&!["completada","cancelada"].includes(w.status));
  const tipoPlanA=(assignment.tipoPlan||template?.tipoPlan||template?.tipo||"horometro").toLowerCase();
  // Plan por calendario (ej: semanal): el vencimiento se mide en días, no en horómetro.
  if(tipoPlanA==="calendario"){
    const nextDueDate=assignment.nextDueDate;
    if(!nextDueDate) return "sin_datos_horometro";
    if(openOT&&template?.requiresCompletion) return "bloqueado_ot_abierta";
    const freq=parseFloat(assignment.frequency||template?.frequency)||0;
    const pct=parseFloat(assignment.pctAnticipacion||template?.pctAnticipacion)||20;
    const advanceDays=freq>0?Math.round(freq*pct/100):7;
    const daysLeft=Math.round((new Date(nextDueDate)-new Date(new Date().toISOString().slice(0,10)))/86400000);
    // "vencido" y "vencido_critico" se consolidan en un solo estado "critico"
    // (Marítimo) — antes eran dos etiquetas de vencido separadas, ahora
    // cualquier plan pasado de fecha es simplemente "Crítico".
    if(daysLeft<0) return "critico";
    if(daysLeft<=advanceDays) return "proximo";
    return "vigente";
  }
  if(!equipment) return "sin_datos_horometro";
  const currentH=parseFloat(equipment.hours)||0;
  const nextDue=parseFloat(assignment.nextDueHours);
  if(isNaN(nextDue)||nextDue===0) return "sin_datos_horometro";
  if(openOT&&template?.requiresCompletion) return "bloqueado_ot_abierta";
  const advance=parseFloat(template?.advanceThresholdHours)||100;
  const hoursLeft=nextDue-currentH;
  if(hoursLeft<0) return "critico";
  if(hoursLeft<=advance) return "proximo";
  return "vigente";
};

