// ── Correlativos exclusivos del módulo Marítimo ──
// Plan: PM-{ID_Equipo}-01, 02, 03... (correlativo único POR equipo)
const nextPlanCode=(equipId)=>{
  const eqCode=equip.find(e=>e.id===equipId)?.code||equipId;
  const existing=plans
    .filter(p=>p.equipId===equipId&&p.code&&p.code.startsWith(`PM-${eqCode}-`))
    .map(p=>parseInt(p.code.split("-").pop())||0);
  const max=existing.length>0?Math.max(...existing):0;
  return `PM-${eqCode}-${String(max+1).padStart(2,"0")}`;
};
// nextPlanOTCode (OT-{códigoPlan}-001, 002...) está definida a nivel de
// módulo junto a nextOTCode — la usan también checkAndAutoGenerateOTs y
// checkAndAutoGenerateOTsFromAssignments para que las OTs regeneradas
// después de cerrar la anterior sigan llevando el código del plan.

const genOT=(plan,allWOs)=>{
const eq=equip.find(e=>e.id===plan.equipId);if(!eq)return null;
const priority=normalizeCriticality(eq.criticality)==="alto"?"alta":normalizeCriticality(eq.criticality)==="medio"?"media":"baja";
const otCode=isMaritimo&&plan.code?nextPlanOTCode(plan.code,allWOs):nextOTCode(allWOs);
// Resolver responsable igual que checkAndAutoGenerateOTs (regeneración post-cierre) —
// antes esta primera OT solo copiaba plan.technician crudo, sin pasar por
// resolveResponsable, y no seteaba assignedToName/responsable/needsAssignment.
const resp=resolveResponsable(plan.responsable||plan.responsablePlan||plan.technician||"",users);
// scheduledDate: plan.nextDueDate ya viene calculado por addPlan para planes
// por calendario (antes quedaba siempre "" — la primera OT de un plan nunca
// mostraba fecha programada, a diferencia de las regeneradas post-cierre).
// Para planes por horómetro no hay fecha de calendario, queda vacío como antes.
return {id:uid(),code:otCode,type:"preventiva",equipId:plan.equipId,planId:plan.id,title:plan.name,priority,status:"asignada",assignedTo:resp.userId||resp.userName,assignedToName:resp.userName,responsable:resp.userId||resp.userName,needsAssignment:!resp.found,createdAt:new Date().toISOString(),scheduledDate:plan.nextDueDate||"",estimatedHours:parseFloat(plan.estimatedHours)||0,actualHours:null,description:`OT automática. Tareas: ${Array.isArray(plan.tasks)?plan.tasks.join(", "):plan.tasks}`,observations:"",parts:[],materialesPlanificados:plan.materialesAsociados||[],source:"plan",urgenciaBacklog:"programable"};
};

const saveTpl=()=>{
if(!tplForm.name||!tplForm.frequency)return;
const nt={id:uid(),...tplForm,frequency:parseInt(tplForm.frequency)||0,estimatedHours:parseFloat(tplForm.estimatedHours)||0,tasks:tplForm.tasks.split("\n").filter(Boolean)};
const upd=[...(taskTemplates||[]),nt];
setData(d=>({...d,taskTemplates:upd}));saveData("taskTemplates",upd);
setShowTplForm(false);setTplForm(EMPTY_TPL);
};

