  const baseH=assignForm.baseHours!==""&&!isNaN(parseFloat(assignForm.baseHours))?parseFloat(assignForm.baseHours):(parseFloat(eq.hours)||0);
  const freq=parseInt(assigningTpl.frequency)||0;
  const code=nextAssignmentCode(planAssignments,eq.code,assigningTpl.code);
  const newAssign={id:uid(),code,templateId:assigningTpl.id,templateCode:assigningTpl.code,equipId:assignForm.equipId,eqmCode:eq.code,nave:activeBarco||"",area:assigningTpl.area,responsable:assignForm.responsable,lastBaseHours:baseH,nextDueHours:baseH+freq,activo:true,createdAt:new Date().toISOString()};
  const upd=[...planAssignments,newAssign];setData(d=>({...d,planAssignments:upd}));saveData("planAssignments",upd);
  setShowAssignModal(false);setAssigningTpl(null);alert(`✅ Plan asignado · ${code}`);
