// ── Editar plan (legacy: edita el plan directo · basado en plantilla: edita solo esa asignación) ──
const openEditPlanAssign=(assign)=>{
  const tplA=assign._isLegacy?null:planTemplates.find(t=>t.id===assign.templateId);
  const refLegacy=assign._planRef;
  setEditPlanAssign(assign);
  setEditPlanAssignForm({
    nombre:assign._isLegacy?assign._nombre:(assign.nombreOverride||tplA?.name||""),
    tipoPlan:((assign.tipoPlan||tplA?.tipoPlan||tplA?.tipo||"horometro").toLowerCase()==="calendario")?"Calendario":"Horometro",
    frequency:String(assign._isLegacy?(assign.frequency||""):(assign.frequency||tplA?.frequency||"")),
    criticidad:(assign.criticidad||"media"),
    area:assign.area||"",
    responsable:assign.responsable||"",
    estimatedHours:String(assign._isLegacy?(assign._estimatedHours||""):(assign.estimatedHoursOverride??tplA?.estimatedHours??"")),
    // Estos 5 campos existen en el modal de creación (EMPTY_PLAN_FORM) pero
    // faltaban acá — mismo bug que en el plan legacy, esta era la otra mitad.
    fechaUltima:assign._isLegacy?(refLegacy?.fechaUltima||""):(assign.fechaUltima||assign.lastExecutionDate||""),
    pctAnticipacion:assign._isLegacy?(refLegacy?.pctAnticipacion??20):(assign.pctAnticipacion??tplA?.pctAnticipacion??20),
    valorRepuesto:String(assign._isLegacy?(refLegacy?.valorRepuesto||""):(assign.valorRepuesto||"")),
    valorServicio:String(assign._isLegacy?(refLegacy?.valorServicio||""):(assign.valorServicio||"")),
    moneda:(assign._isLegacy?refLegacy?.moneda:assign.moneda)||"USD",
    materialesAsociados:assign._isLegacy?(assign._planRef?.materialesAsociados||[]):(assign.materialesAsociados||[]),
  });
  setShowEditPlanAssign(true);
};
const saveEditPlanAssign=()=>{
  if(!editPlanAssign||!editPlanAssignForm) return;
  const f=editPlanAssignForm;
  const freq=parseFloat(f.frequency);
  if(isNaN(freq)||freq<=0){alert("Frecuencia inválida");return;}
  const tipoPlanNorm=f.tipoPlan==="Calendario"?"calendario":"horometro";
  const cambios=[];
  const pushCambio=(campo,antes,despues)=>{if(String(antes??"")!==String(despues??"")) cambios.push(`${campo}: "${antes??"—"}" → "${despues??"—"}"`);};

  if(editPlanAssign._isLegacy){
    const pl=editPlanAssign._planRef;
    const tipoAntes=(pl.tipoPlan||"horometro").toLowerCase();
    pushCambio("Nombre",pl.name,f.nombre);
    pushCambio("Tipo",tipoAntes==="calendario"?"Calendario":"Horometro",f.tipoPlan);
    pushCambio("Frecuencia",`${pl.frequency||0}${tipoAntes==="calendario"?"d":"h"}`,`${freq}${tipoPlanNorm==="calendario"?"d":"h"}`);
    pushCambio("Criticidad",pl.criticidad,f.criticidad);
    pushCambio("Área",pl.area,f.area);
    pushCambio("Responsable",pl.responsable,f.responsable);
    pushCambio("Fecha última OT",pl.fechaUltima,f.fechaUltima);
    // La base de "próximo PM" (solo calendario) usa la fecha última YA
    // corregida en este mismo guardado, no la anterior — si se edita acá
    // para arreglar un desfase, el próximo vencimiento tiene que recalcularse
    // desde el valor corregido, no desde el que se está reemplazando.
    const nextDueDateCalc=tipoPlanNorm==="calendario"?(()=>{const base=f.fechaUltima||pl.fechaUltima||new Date().toISOString().slice(0,10);const d=new Date(base);d.setDate(d.getDate()+freq);return d.toISOString().slice(0,10);})():null;
    const updatedPlan={
      ...pl,
      name:f.nombre,
      frequency:freq,
      tipoPlan:tipoPlanNorm,
      unidad:tipoPlanNorm==="calendario"?"DÍAS":"HORAS",
      criticidad:f.criticidad,
      criticidadPlan:f.criticidad,
      area:f.area,
      responsable:f.responsable,
      responsablePlan:f.responsable,
      technician:f.responsable,
      estimatedHours:parseFloat(f.estimatedHours)||0,
      fechaUltima:f.fechaUltima||pl.fechaUltima,
      lastExecutionDate:f.fechaUltima||pl.lastExecutionDate,
      pctAnticipacion:parseFloat(f.pctAnticipacion)||20,
      valorRepuesto:parseFloat(f.valorRepuesto)||0,
      valorServicio:parseFloat(f.valorServicio)||0,
      moneda:f.moneda||"USD",
      materialesAsociados:f.materialesAsociados||[],
      ...(tipoPlanNorm==="horometro"
        ?{horometroTarget:(parseFloat(pl.lastHorometro)||0)+freq,nextDueDate:null,proximaFecha:""}
        :{horometroTarget:null,nextDueDate:nextDueDateCalc,proximaFecha:nextDueDateCalc||""}),
      historialCambios:[
        {ts:new Date().toISOString(),usuario:user.name,accion:"editado",detalle:cambios.length>0?cambios.join(" · "):"Guardado sin cambios"},
        ...(pl.historialCambios||[]),
      ],
    };
    const updP=(data.plans||[]).map(p=>p.id===pl.id?updatedPlan:p);
    setData(d=>({...d,plans:updP}));
    saveData("plans",updP);
  } else {
    const a0=editPlanAssign;
    const tipoAntes=(a0.tipoPlan||"horometro").toLowerCase();
    const tplA=planTemplates.find(t=>t.id===a0.templateId);
    pushCambio("Nombre",a0.nombreOverride||tplA?.name||"",f.nombre);
    pushCambio("Tipo",tipoAntes==="calendario"?"Calendario":"Horometro",f.tipoPlan);
    pushCambio("Frecuencia",`${a0.frequency||tplA?.frequency||0}${tipoAntes==="calendario"?"d":"h"}`,`${freq}${tipoPlanNorm==="calendario"?"d":"h"}`);
    pushCambio("Criticidad",a0.criticidad,f.criticidad);
    pushCambio("Área",a0.area,f.area);
    pushCambio("Responsable",a0.responsable,f.responsable);
    pushCambio("Fecha última OT",a0.fechaUltima||a0.lastExecutionDate,f.fechaUltima);
    // Misma razón que en la rama legacy: recalcular desde f.fechaUltima
    // (el valor recién corregido), no desde a0.lastExecutionDate (el viejo).
    const nextDueDateCalc=tipoPlanNorm==="calendario"?(()=>{const base=f.fechaUltima||a0.lastExecutionDate||new Date().toISOString().slice(0,10);const d=new Date(base);d.setDate(d.getDate()+freq);return d.toISOString().slice(0,10);})():null;
    const upd=planAssignments.map(a=>a.id===a0.id?{
      ...a,
      nombreOverride:f.nombre,
      frequency:freq,
      tipoPlan:tipoPlanNorm,
      criticidad:f.criticidad,
      area:f.area,
      responsable:f.responsable,
      estimatedHoursOverride:parseFloat(f.estimatedHours)||0,
      fechaUltima:f.fechaUltima||a0.fechaUltima,
      pctAnticipacion:parseFloat(f.pctAnticipacion)||20,
      valorRepuesto:parseFloat(f.valorRepuesto)||0,
      valorServicio:parseFloat(f.valorServicio)||0,
      moneda:f.moneda||"USD",
      materialesAsociados:f.materialesAsociados||[],
      ...(tipoPlanNorm==="horometro"
        ?{nextDueHours:(parseFloat(a.lastBaseHours)||0)+freq,nextDueDate:null}
        :{nextDueHours:null,nextDueDate:nextDueDateCalc,lastExecutionDate:f.fechaUltima||a.lastExecutionDate||new Date().toISOString().slice(0,10)}),
      historialCambios:[
        {ts:new Date().toISOString(),usuario:user.name,accion:"editado",detalle:cambios.length>0?cambios.join(" · "):"Guardado sin cambios"},
        ...(a.historialCambios||[]),
      ],
    }:a);
    setData(d=>({...d,planAssignments:upd}));
    saveData("planAssignments",upd);
  }
  setShowEditPlanAssign(false);setEditPlanAssign(null);setEditPlanAssignForm(null);setSelectedAssignDetail(null);
};
const deleteBulkAssigns=()=>{if(!window.confirm(`¿Eliminar ${selAssignIds.size} asignación(es)?`))return;const upd=planAssignments.filter(a=>!selAssignIds.has(a.id));const updPlans=(data.plans||[]).filter(p=>!selAssignIds.has(p.id));setData(d=>({...d,planAssignments:upd,plans:updPlans}));saveData("planAssignments",upd);saveData("plans",updPlans);setSelAssignIds(new Set());setSelectedAssignDetail(null);};
const generateOTFromAssignment=(assign)=>{
  if(assign._isLegacy){alert("Este plan legacy ya generó su OT al crearse. Revisa la vista WorkOrders.");return;}
  const tpl=planTemplates.find(t=>t.id===assign.templateId);
  if(!tpl){alert("Plantilla no encontrada");return;}
  const openOT=(wos||[]).find(w=>w.assignmentId===assign.id&&!["completada","cancelada"].includes(w.status));
  if(openOT){alert(`Ya existe una OT abierta: ${openOT.code}`);return;}
  setPendingAssignment(assign);setAssignOTMechanic((users||[]).find(u=>u.role==="mecanico")?.id||"");setAssignOTDate(new Date().toISOString().slice(0,10));setShowAssignOTModal(true);
};
const confirmAssignOT=()=>{
  if(!pendingAssignment||!assignOTMechanic){alert("Selecciona un mecánico");return;}
  const assign=pendingAssignment;const tpl=planTemplates.find(t=>t.id===assign.templateId);const eq=equip.find(e=>e.id===assign.equipId);
  if(!tpl||!eq)return;
  const nc=normalizeCriticality(tpl.criticidad);
  const priority=nc==="alto"?"alta":nc==="medio"?"media":"baja";
  const otCode=nextOTCode(wos);
  const newOT={id:uid(),code:otCode,type:"preventiva",source:"plan",assignmentId:assign.id,templateId:tpl.id,equipId:assign.equipId,title:tpl.name,priority,status:"asignada",assignedTo:assignOTMechanic,createdAt:new Date().toISOString(),scheduledDate:assignOTDate||new Date().toISOString().slice(0,10),estimatedHours:0,actualHours:null,description:`Plan ${tpl.code}: ${tpl.name}\nÁrea: ${tpl.area||"—"}\nTareas: ${(tpl.tasks||[]).map(t=>typeof t==="object"?t.name:t).join(", ")||"—"}`,observations:"",parts:[],materialesPlanificados:assign.materialesAsociados||tpl.materiales||[],urgenciaBacklog:"programable",log:[{ts:new Date().toISOString(),action:"creada",user:user.name,detail:`OT desde asignación ${assign.code} · Plan ${tpl.code}`}]};
  const updW=[...wos,newOT];setData(d=>({...d,wos:updW}));saveData("workOrders",updW);
  setShowAssignOTModal(false);setPendingAssignment(null);setAssignOTMechanic("");setAssignOTDate("");
  alert(`✅ OT ${otCode} generada`);
};

