const compressVehiclePhoto=(file,cb)=>{
  const reader=new FileReader();
  reader.onload=e=>{
    const img=new Image();
    img.onload=()=>{
      const maxW=1200;
      const maxH=1600;
      let w=img.width,h=img.height;
      if(w>maxW){h=Math.round(h*maxW/w);w=maxW;}
      if(h>maxH){w=Math.round(w*maxH/h);h=maxH;}
      const canvas=document.createElement("canvas");
      canvas.width=w;canvas.height=h;
      const ctx=canvas.getContext("2d");
      ctx.fillStyle="#ffffff";
      ctx.fillRect(0,0,w,h);
      ctx.drawImage(img,0,0,w,h);
      const b64=canvas.toDataURL("image/jpeg",0.72);
      if(b64.length>500000){
        const canvas2=document.createElement("canvas");
        const scale=Math.sqrt(500000/b64.length);
        canvas2.width=Math.round(w*scale);
        canvas2.height=Math.round(h*scale);
        canvas2.getContext("2d").drawImage(img,0,0,canvas2.width,canvas2.height);
        cb(canvas2.toDataURL("image/jpeg",0.70));
      } else {
        cb(b64);
      }
    };
    img.src=e.target.result;
  };
  reader.readAsDataURL(file);
};

