                    <div className="flex flex-wrap gap-x-4 gap-y-1 text-xs">
                      <span className="text-emerald-600 font-medium">✓ {op.sinObs} sin obs.</span>
                      <span className={op.conObs>0?"text-amber-600 font-medium":"text-gray-400"}>
                        ⚠️ {op.conObs} con obs. {op.conObs>0&&`(${obsRate}%)`}
                      </span>
                      {avg!=null&&<span className={`font-medium ${durColor}`}>⏱ {avg} min prom.</span>}
                      <span className="text-gray-400">{op.equipos.size} equipo{op.equipos.size!==1?"s":""}</span>
                      {op.lastDate&&<span className="text-gray-400">Último: {fmtDT(op.lastDate).slice(0,10)}</span>}
                    </div>
