// ─── RESOLUCIÓN DE RESPONSABLE POR NOMBRE ────────────────────────────────────
function resolveResponsable(nombrePlan, users) {
  if(!nombrePlan||!nombrePlan.trim()) return{userId:"",userName:"",found:false};
  const normalizar=s=>(s||"").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").trim();
  const nombreNorm=normalizar(nombrePlan);
  // 1. Coincidencia exacta normalizada
  let usuario=(users||[]).find(u=>normalizar(u.name)===nombreNorm);
  if(usuario) return{userId:usuario.id,userName:usuario.name,found:true};
  // 2. Coincidencia parcial: uno contiene al otro
  usuario=(users||[]).find(u=>{
    const uNorm=normalizar(u.name);
    return uNorm.includes(nombreNorm)||nombreNorm.includes(uNorm);
  });
  if(usuario) return{userId:usuario.id,userName:usuario.name,found:true};
  // 3. Coincidencia por palabras clave (todas las palabras de +3 letras deben aparecer)
  const words=nombreNorm.split(/\s+/).filter(w=>w.length>2);
  if(words.length>0){
    usuario=(users||[]).find(u=>{
      const uNorm=normalizar(u.name);
      return words.every(w=>uNorm.includes(w));
    });
    if(usuario) return{userId:usuario.id,userName:usuario.name,found:true};
  }
  return{userId:"",userName:nombrePlan.trim(),found:false};
}

// ─── APRENDIZAJE DE HORÓMETRO PROMEDIO ───────────────────────────────────────
function calcAvgLearned(equipId, wos, hourmeterReadings) {
  // Usa lecturas de horómetro (readingDate = fecha real, no timestamp de imputación)
  // en vez de OTs cerradas. Fórmula: (horo2-horo1)/(fecha2-fecha1 en días).
  const readings=(hourmeterReadings||[])
    .filter(r=>
      r.equipId===equipId&&
      r.readingDate&&
      r.hours!=null&&
      !isNaN(parseFloat(r.hours))
    )
    .map(r=>({
      h:parseFloat(r.hours),
      fecha:new Date(r.readingDate+"T12:00:00"),
    }))
    .filter(r=>!isNaN(r.fecha.getTime()))
    .sort((a,b)=>a.fecha-b.fecha);

  if(readings.length<2) return null;

  let sumPeso=0, sumRatio=0;
  for(let i=1;i<readings.length;i++){
    const deltaH=readings[i].h-readings[i-1].h;
    const deltaD=(readings[i].fecha-readings[i-1].fecha)/(1000*60*60*24);
    if(deltaH<=0||deltaD<=0) continue;
    const ratio=deltaH/deltaD;
    if(ratio<0.1||ratio>24){
      console.warn(`⚠️ calcAvgLearned ratio incoherente: ${ratio.toFixed(2)}h/día`);
      continue;
    }
    sumPeso+=deltaD;
    sumRatio+=ratio*deltaD;
  }
  if(sumPeso===0) return null;
  return Math.round((sumRatio/sumPeso)*10)/10;
}

// ─── ESTIMACIÓN DE FECHA DESDE HORÓMETRO ─────────────────────────────────────
function estimarFechaDesdeHorometro(hActual,hObjetivo,eq){
  const avg=(eq?.avgPreference==="manual"
    ?parseFloat(eq?.avgOperatingHours)||null
    :eq?.avgOperatingHoursLearned||parseFloat(eq?.avgOperatingHours)||null
  );
  if(!avg||avg<=0) return null;
  const horasFaltantes=hObjetivo-hActual;
  if(horasFaltantes<=0) return new Date().toISOString().slice(0,10);
  const diasFaltantes=Math.ceil(horasFaltantes/avg);
  const fecha=new Date();
  fecha.setDate(fecha.getDate()+diasFaltantes);
  return fecha.toISOString().slice(0,10);
}

// Igual que estimarFechaDesdeHorometro pero además devuelve el desglose en
// días/semanas (pedido explícito para los planes por horómetro de
// Marítimo, que ahora cargan un único promedio manual en horas mensuales
// — ver avgHorasMensuales en Equipment, ya convertido a horas/día en
// avgOperatingHours al guardar el equipo). No duplica el cálculo de
// fecha, solo lo reexpresa para mostrarlo en el formulario de planes.
function proyeccionPMHorometro(hActual,hObjetivo,eq){
  const avg=(eq?.avgPreference==="manual"
    ?parseFloat(eq?.avgOperatingHours)||null
    :eq?.avgOperatingHoursLearned||parseFloat(eq?.avgOperatingHours)||null
  );
  if(!avg||avg<=0) return null;
  const horasFaltantes=hObjetivo-hActual;
  if(horasFaltantes<=0) return{vencido:true,horasFaltantes,dias:0,semanas:0,fecha:new Date().toISOString().slice(0,10)};
  const dias=Math.ceil(horasFaltantes/avg);
  const fecha=new Date();
  fecha.setDate(fecha.getDate()+dias);
  return{vencido:false,horasFaltantes,dias,semanas:Math.round(dias/7*10)/10,fecha:fecha.toISOString().slice(0,10)};
}

// ─── AUTO PM OT GENERATION ───────────────────────────────────────────────────
function checkAndAutoGenerateOTs(plans, wos, equip, checklists, users) {
  const liveHours = (equipId) => {
    const eq = equip.find(e=>e.id===equipId);
    const horometroOficial = eq?.hours || 0;
    const latestCL = (checklists||[])
      .filter(c=>c.equipId===equipId)
      .sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt))[0];
    if(!latestCL || latestCL.horometro == null) return horometroOficial;
    const diferencia = latestCL.horometro - horometroOficial;
    if(diferencia > 50 || diferencia < -10){
      console.warn(`⚠️ Horómetro inconsistente ${eq?.code}: checklist=${latestCL.horometro}h vs oficial=${horometroOficial}h — usando oficial`);
      return horometroOficial;
    }
    return latestCL.horometro;
  };
  const addDays=(iso,n)=>{const d=new Date(iso);d.setDate(d.getDate()+Math.round(n));return d.toISOString().slice(0,10);};
  const newOTs=[];
  const today=new Date().toISOString().slice(0,10);
  const mkTareasStr=tasks=>Array.isArray(tasks)?tasks.map(t=>typeof t==="string"?t:(t.name||t.description||JSON.stringify(t))).join(", "):tasks||"—";
  const mkPriority=eq=>normalizeCriticality(eq.criticality)==="alto"?"alta":normalizeCriticality(eq.criticality)==="medio"?"media":"baja";

  // Pasada 1: planes por horómetro con anticipación
  for(const plan of plans){
    if((plan.tipoPlan||"").toLowerCase()==="calendario") continue;
    if(plan.activo===false) continue;
    const target=parseFloat(plan.horometroTarget)||0;
    if(target===0) continue;
    const hActual=liveHours(plan.equipId);
    const freq=parseFloat(plan.frequency)||0;
    const pct=parseFloat(plan.pctAnticipacion)||20;
    const triggerH=target-(freq*pct/100);
    if(hActual<triggerH) continue;
    if(wos.some(w=>w.planId===plan.id&&!["completada","cancelada"].includes(w.status))) continue;
    const eq=equip.find(e=>e.id===plan.equipId); if(!eq) continue;
    const resp=resolveResponsable(plan.responsable||plan.responsablePlan||plan.technician||"",users);
    const allWOs=[...wos,...newOTs];
    newOTs.push({
      id:uid(),code:plan.code?nextPlanOTCode(plan.code,allWOs):nextOTCode(allWOs),type:"preventiva",equipId:plan.equipId,
      planId:plan.id,title:plan.name,priority:mkPriority(eq),
      status:"pendiente",needsAssignment:!resp.found,assignedTo:resp.userId||resp.userName,
      assignedToName:resp.userName,responsable:resp.userId||resp.userName,
      createdAt:new Date().toISOString(),scheduledDate:estimarFechaDesdeHorometro(hActual,target,eq)||today,
      fechaEstimadaCalculo:estimarFechaDesdeHorometro(hActual,target,eq),
      estimatedHours:parseFloat(plan.estimatedHours)||0,actualHours:null,
      description:`OT automática. Horómetro: ${hActual}h / Meta: ${target}h\nTareas: ${mkTareasStr(plan.tasks)}`,
      observations:"",parts:[],source:"plan",autoGenerated:true,urgenciaBacklog:hActual>=target?"vencida":"proxima"
    });
  }

  // Pasada 2: planes por calendario con anticipación
  for(const plan of plans){
    if((plan.tipoPlan||"").toLowerCase()!=="calendario") continue;
    if(plan.activo===false) continue;
    const nextDue=plan.nextDueDate||plan.proximaFecha;
    if(!nextDue) continue;
    const freq=parseFloat(plan.frequency)||0;
    const pct=parseFloat(plan.pctAnticipacion)||20;
    const triggerDate=freq>0?addDays(nextDue,-(freq*pct/100)):nextDue;
    if(today<triggerDate) continue;
    if(wos.some(w=>w.planId===plan.id&&!["completada","cancelada"].includes(w.status))) continue;
    const eq=equip.find(e=>e.id===plan.equipId); if(!eq) continue;
    const resp=resolveResponsable(plan.responsable||plan.responsablePlan||plan.technician||"",users);
    const allWOs=[...wos,...newOTs];
    newOTs.push({
      id:uid(),code:plan.code?nextPlanOTCode(plan.code,allWOs):nextOTCode(allWOs),type:"preventiva",equipId:plan.equipId,
      planId:plan.id,title:plan.name,priority:mkPriority(eq),
      status:"pendiente",needsAssignment:!resp.found,assignedTo:resp.userId||resp.userName,
      assignedToName:resp.userName,responsable:resp.userId||resp.userName,
      createdAt:new Date().toISOString(),scheduledDate:nextDue||today,
      estimatedHours:parseFloat(plan.estimatedHours)||0,actualHours:null,
      description:`OT automática por fecha. Fecha programada: ${nextDue}\nTareas: ${mkTareasStr(plan.tasks)}`,
      observations:"",parts:[],source:"plan",autoGenerated:true,tipoDisparo:"calendario",
      urgenciaBacklog:today>=nextDue?"vencida":"proxima"
    });
  }

  return newOTs;
}

function checkAndAutoGenerateOTsFromAssignments(planAssignments,planTemplates,wos,equip,users,refDate=null){
  const todayStr=refDate||new Date().toISOString().slice(0,10);
  const newOTs=[];
  for(const assign of (planAssignments||[])){
    if(!assign.activo) continue;
    const tpl=(planTemplates||[]).find(t=>t.id===assign.templateId);
    // El tipoPlan a nivel de asignación tiene prioridad — permite decouplar
    // una asignación de su plantilla al editarla individualmente.
    const tipoPlan=(assign.tipoPlan||tpl?.tipoPlan||tpl?.tipo||"horometro").toLowerCase();
    const eq=equip.find(e=>e.id===assign.equipId); if(!eq) continue;
    if((wos||[]).some(w=>w.assignmentId===assign.id&&!["completada","cancelada"].includes(w.status))) continue;
    const priority=normalizeCriticality(eq.criticality)==="alto"?"alta":normalizeCriticality(eq.criticality)==="medio"?"media":"baja";
    const tareasStr=Array.isArray(tpl?.tasks)
      ?tpl.tasks.map(t=>typeof t==="string"?t:(t.name||t.description||JSON.stringify(t))).join(", ")
      :(tpl?.tasks||"—");
    // Buscar responsable por ID primero (más confiable), luego por nombre normalizado
    const idResp=assign.responsableId||assign.technician_id||"";
    const nombreResp=assign.responsable||assign.responsablePlan||tpl?.responsable||tpl?.technician||"";
    let resp={userId:"",userName:nombreResp,found:false};
    if(idResp){
      const uById=users.find(u=>u.id===idResp&&!u.deleted);
      if(uById) resp={userId:uById.id,userName:uById.name,found:true};
    }
    if(!resp.found&&nombreResp){
      resp=resolveResponsable(nombreResp,users);
    }
    if(!resp.found){
      console.warn(`⚠️ Responsable no encontrado para plan "${assign.code||assign.id}": "${nombreResp}"`);
    }
    if(tipoPlan==="calendario"){
      const nextDueDate=assign.nextDueDate;
      if(!nextDueDate) continue;
      const freq=parseFloat(assign.frequency||tpl?.frequency)||0;
      const pct=parseFloat(assign.pctAnticipacion||tpl?.pctAnticipacion)||20;
      const diasAnticipacion=freq>0?Math.round(freq*pct/100):0;
      const triggerDate=(()=>{const d=new Date(nextDueDate);d.setDate(d.getDate()-diasAnticipacion);return d.toISOString().slice(0,10);})();
      if(todayStr<triggerDate) continue;
      const allWOs=[...wos,...newOTs];
      const diasVenc=Math.round((new Date(todayStr)-new Date(nextDueDate))/(86400000));
      newOTs.push({
        id:uid(),code:assign.code?nextPlanOTCode(assign.code,allWOs):nextOTCode(allWOs),type:"preventiva",
        equipId:assign.equipId,assignmentId:assign.id,templateId:assign.templateId,
        title:assign.nombreOverride||tpl?.name||assign.templateCode||"PM Automático",
        priority,status:"pendiente",needsAssignment:!resp.found,
        assignedTo:resp.userId||"",assignedToName:resp.userName||nombreResp||"",
        responsable:resp.userId||resp.userName||nombreResp||"",
        createdAt:new Date().toISOString(),scheduledDate:nextDueDate||todayStr,
        estimatedHours:parseFloat(tpl?.estimatedHours)||0,actualHours:null,
        description:`OT automática. Plan calendario: vence ${nextDueDate}\nPlan: ${assign.code}\nTareas: ${tareasStr}`,
        observations:"",parts:[],source:"planAssignment",autoGenerated:true,
        urgenciaBacklog:diasVenc>=15?"emergencia":diasVenc>=8?"urgente_24_48h":"urgente_0_24h",
      });
    } else {
      const nextDue=parseFloat(assign.nextDueHours)||0;
      if(nextDue===0) continue;
      const currentH=parseFloat(eq.hours)||0;
      const freq=parseFloat(assign.frequency||tpl?.frequency)||0;
      const pct=parseFloat(assign.pctAnticipacion||tpl?.pctAnticipacion)||20;
      const triggerH=nextDue-(freq*pct/100);
      if(currentH<triggerH) continue;
      const allWOs=[...wos,...newOTs];
      const horasVenc=currentH-nextDue;
      newOTs.push({
        id:uid(),code:assign.code?nextPlanOTCode(assign.code,allWOs):nextOTCode(allWOs),type:"preventiva",
        equipId:assign.equipId,assignmentId:assign.id,templateId:assign.templateId,
        title:assign.nombreOverride||tpl?.name||assign.templateCode||"PM Automático",
        priority,status:"pendiente",needsAssignment:!resp.found,
        assignedTo:resp.userId||"",assignedToName:resp.userName||nombreResp||"",
        responsable:resp.userId||resp.userName||nombreResp||"",
        createdAt:new Date().toISOString(),scheduledDate:estimarFechaDesdeHorometro(currentH,nextDue,eq)||todayStr,
        estimatedHours:parseFloat(tpl?.estimatedHours)||0,actualHours:null,
        description:`OT automática. Horómetro: ${currentH}h / Meta: ${nextDue}h\nPlan: ${assign.code}\nTareas: ${tareasStr}`,
        observations:"",parts:[],source:"planAssignment",autoGenerated:true,
        urgenciaBacklog:horasVenc>=100?"emergencia":horasVenc>=50?"urgente_0_24h":"urgente_24_48h",
        fechaEstimadaCalculo:estimarFechaDesdeHorometro(currentH,nextDue,eq),
      });
    }
  }
  return newOTs;
}

// ─── REPUESTOS ────────────────────────────────────────────────────────────────
