          {form.firmaOrganizador
            ?<img src={form.firmaOrganizador} className="h-20 max-w-[240px] object-contain"/>
            :<button onClick={()=>setShowSig("organizadorFirma")} className="h-10 w-32 border border-dashed border-gray-400 text-gray-400 text-[10px] rounded hover:border-red-800 hover:text-red-800 transition">Firmar</button>
          }
          {form.firmaOrganizador&&<button onClick={()=>setShowSig("organizadorFirma")} className="text-[10px] text-gray-400 underline">Cambiar</button>}
