useEffect(()=>{
  if(!user) return;
  let timer;
  let warnTimer;
  const reset=()=>{
    clearTimeout(timer);
    clearTimeout(warnTimer);
    warnTimer=setTimeout(()=>{
      if(window.confirm("Tu sesión cerrará en 5 minutos por inactividad. ¿Continuar?")){
        reset();
      }
    },25*60*1000);
    timer=setTimeout(()=>{
      setUser(null);
      setPage("dashboard");
      alert("Sesión cerrada por inactividad.");
    },30*60*1000);
  };
  const events=["mousemove","keydown","click","touchstart","scroll"];
  events.forEach(e=>window.addEventListener(e,reset));
  reset();
  return()=>{
    clearTimeout(timer);
    clearTimeout(warnTimer);
    events.forEach(e=>window.removeEventListener(e,reset));
  };
},[user]);

useEffect(()=>{
  if(!user) return;
  const handleVisibility=()=>{
    if(document.visibilityState==="visible"){
      const last=localStorage.getItem("mantek_last_active");
      if(last&&Date.now()-parseInt(last)>30*60*1000){
        setUser(null);
        setPage("dashboard");
      }
    } else {
      localStorage.setItem("mantek_last_active",Date.now().toString());
    }
  };
  document.addEventListener("visibilitychange",handleVisibility);
  return()=>document.removeEventListener("visibilitychange",handleVisibility);
},[user]);

