useEffect(()=>{
  if(!user||!activeModule||user.role!=="supervisor") return;
  const coll=getActiveCOLL(activeModule,activeBarco);
  const allUsers=data.users||[];
  const subs=allUsers.map(u=>{
    const ref=doc(db, coll, "presence_"+u.id);
    return onSnapshot(ref, snap=>{
      if(!snap.exists()) return;
      const d=snap.data();
      setOnlineUsers(prev=>{
        const filtered=prev.filter(p=>p.userId!==d.userId);
        const isOnline=d.online&&(Date.now()-d.lastSeen)<PRESENCE_TTL;
        return isOnline?[...filtered,d]:filtered;
      });
    });
  });
  presenceUnsub.current=()=>subs.forEach(u=>u());
  return()=>presenceUnsub.current?.();
},[user, activeModule, data.users]);

